pub(crate) fn parse_object_type_extension(p: &mut GraphqlParser) -> ParsedSyntax {
    let m = p.start();

    p.bump(T![extend]);
    p.bump(T![type]);

    parse_name(p).or_add_diagnostic(p, expected_name);

    // implements interface is optional
    let has_implements = parse_implements_interface(p).ok().is_some();

    let pos = p.source().position();
    DirectiveList.parse_list(p);
    let has_directives = p.source().position() != pos;

    // fields definition is optional
    let has_fields = parse_fields_definition(p).ok().is_some();

    // an object type extension must add at least one of an implements clause,
    // a directive, or a fields definition
    if !has_implements && !has_directives && !has_fields {
        p.error(expected_object_type_extension(p, p.cur_range()));
    }

    Present(m.complete(p, GRAPHQL_OBJECT_TYPE_EXTENSION))
